#!/bin/bash
set -e

cd Dependencies/zstd/build/cmake

$CMAKE_COMMAND . -DCMAKE_INSTALL_PREFIX=$INSTALL_PREFIX -DBUILD_SHARED_LIBS=false -DZSTD_BUILD_SHARED=false -DZSTD_LEGACY_SUPPORT=false -DZSTD_MULTITHREAD_SUPPORT=false -DZSTD_BUILD_PROGRAMS=false -DZSTD_BUILD_TESTS=false -DZSTD_BUILD_CONTRIB=false -DCMAKE_BUILD_TYPE=$CMAKE_BUILD_TYPE -DCMAKE_C_FLAGS="$FLAGS"
$MAKE install
